7|const IDS = ["calma", "alegria", "tristeza", "suspenso", "misterio", "aventura", "combate", "asombro"];
8|const questions = {
9|  emotion: {
10|    type: "choice",
11|    instructions: "Which single emotion best matches the mood of this passage?",
12|    criteria: {
13|      calma: "Calm, peaceful, safe; nothing threatening happens",
14|      alegria: "Joyful, warm, celebratory; good things happen",
15|      tristeza: "Sad, mournful, loss or grief",
16|      suspenso: "Tense, anxious, danger may strike at any moment",
17|      misterio: "Mysterious, strange, uncanny; things defy explanation",
18|      aventura: "Adventurous, journeying into the unknown with wonder",
19|      combate: "Violent conflict, fighting, ferocious attack",
20|      asombro: "Awe, amazement, wonder at something spectacular",
21|    },
22|  },
23|  intensity: {
24|    type: "score",
25|    instructions: "How intense are the stakes and energy of this passage?",
26|    criteria: [
27|      "very quiet, low stakes",
28|      "calm, mild tension",
29|      "moderate stakes and energy",
30|      "high stakes, dramatic",
31|      "overwhelming, peak stakes",
32|    ],
33|  },
34|  tempo: {
35|    type: "score",
36|    instructions: "How fast does this passage move?",
37|    criteria: ["still, slow, lingering", "unhurried, gentle movement", "steady, moderate pace", "fast, urgent action", "frantic, rapid action"],
38|  },
39|};
40|
41|let sawUnknown = false;
42|let sawMissing = false;
43|for (const p of passages) {
44|  const t0 = Date.now();
45|  const res = await fetch("https://api.typesafe.ai/v1/systemone", {
46|    method: "POST",
47|    headers: { Authorization: `Bearer ${key}`, "Content-Type": "application/json" },
48|    body: JSON.stringify({ model: "jev-1.14.0", state: p.text, questions }),
49|  });
50|  const ms = Date.now() - t0;
51|  const body = await res.json().catch(() => null);
52|  if (!res.ok) {
53|    console.log(`${p.id}: FAIL status=${res.status} latency_ms=${ms} error=${body?.error?.message ?? JSON.stringify(body)?.slice(0, 200)}`);
54|    continue;
55|  }
56|  const a = body.answers ?? {};
57|  const probs = a.emotion?.probabilities ?? {};
58|  const keys = Object.keys(probs);
59|  const missing = IDS.filter((id) => !(id in probs));
60|  const extra = keys.filter((k) => !IDS.includes(k));
61|  if (a.emotion?.choice === "unknown") sawUnknown = true;
62|  if (missing.length > 0) sawMissing = true;
63|  const sum = keys.reduce((t, k) => t + (probs[k] ?? 0), 0);
64|  const vec = IDS.map((id) => `${id}=${(probs[id] ?? NaN).toFixed(3)}`).join(" ");
65|  const norm = (s) => (typeof s?.score === "number" ? (s.score / 4).toFixed(3) : "?");
66|  console.log(
67|    `${p.id}: OK status=${res.status} latency_ms=${ms} model=${body.model} ` +
68|      `choice=${a.emotion?.choice} confidence=${a.emotion?.confidence} sum=${sum.toFixed(3)} ` +
69|      `missing=[${missing}] extra=[${extra}]`
70|  );
71|  console.log(`  probs: ${vec}`);
72|  console.log(
73|    `  intensity score=${a.intensity?.score} norm=${norm(a.intensity)} conf=${a.intensity?.confidence} ` +
74|      `tempo score=${a.tempo?.score} norm=${norm(a.tempo)} conf=${a.tempo?.confidence}`
75|  );
76|  console.log(`  usage=${JSON.stringify(body.usage ?? null)}`);
77|}
78|console.log(`saw_unknown=${sawUnknown} saw_missing_ids=${sawMissing}`);
79|console.log("pricing: jev-quickstart docs carry no jev-1.14.0 price, cost unknown");

